class Hylle:
    def __init__(self, navn, plasser):
        self._navn = navn
        self._plasser = plasser
        self._n = 0

    def er_ledig(self):
        return self._n < self._plasser

    def sett_inn(self):
        self._n = self._n + 1

    def __str__(self):
        return self._navn + ":" + str(self._n)

